      if(!pool.length) pool=ids.slice();
      ix=Math.floor(rr()*pool.length); plan.push({id:pool.splice(ix,1)[0],at:t,tries:0,on:0});
      t+=EV.gap[0]+rr()*(EV.gap[1]-EV.gap[0]);
