function flowGlyph(c,shape,x,y,u){
  c.beginPath();
  if(shape==='dia'){ c.moveTo(x,y-u); c.lineTo(x+u*0.8,y); c.lineTo(x,y+u); c.lineTo(x-u*0.8,y); }
