}
function debrisWreck(ev,pt){
  var L=[], c=null, k, a=0, wx, wy, E=evS(), seed=(((G.seed>>>0)^Math.imul((((ev.n|0)&255)<<5)+((pt.i|0)&31)+1,2654435761))>>>0)||1;
