EVENTS.debris={name:'ORBITAL DEBRIS',sub:'GET CLEAR',warn:22,dur:20,r:300,fade:4,col:'#ffcf5a',
  pick:function(ev){
    var p=G.player, got=null;
    evStream(ev,function(){
      var k, a, d, x, y;
      for(k=0;k<60&&!got;k++){
        a=rr()*6.2832; d=500+rr()*500; x=p.x+Math.cos(a)*d; y=p.y+Math.sin(a)*d;
